languages.javascript:
const result = new Map();
for (const key of keys) if (source.has(key) && !result.has(key)) result.set(key, source.get(key));
return result;

languages.python:
result = {}
for key in keys:
    if key in source and key not in result:
        result[key] = source[key]
return result

languages.cpp:
std::decay_t<decltype(source)> result;
for (const auto& key : keys) if (source.contains(key) && !result.contains(key)) result[key] = source.at(key);
return result;

languages.rust:
let mut result = vgraph::Map::new();
for key in keys.iter() {
    if let Some(value) = source.get(key) {
        if !result.contains(key) { result.insert(key.clone(), value); }
    }
}
return result;

languages.java:
var result = new java.util.LinkedHashMap<>(source);
result.clear();
for (var key : keys) if (source.containsKey(key) && !result.containsKey(key)) result.put(key, source.get(key));
return result;

languages.go:
result := source.Empty()
for _, key := range *keys {
	if value, ok := source.Get(key); ok {
		if _, done := result.Get(key); !done {
			result.Put(key, value)
		}
	}
}
return result
